INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype) VALUES
  ('9a66fc96-c9a0-47f7-b07a-bd8c8e082750', 'A', 'misconception', $a$equal-mass implies equal moles of the target atom, ignoring molar mass and atoms-per-formula-unit$a$),
  ('9a66fc96-c9a0-47f7-b07a-bd8c8e082750', 'B', 'process_step_confusion', $a$uses oxygen count of a single PO4 group (4) instead of the full 8, dropping the subscript outside the parentheses$a$),
  ('9a66fc96-c9a0-47f7-b07a-bd8c8e082750', 'C', 'partial_truth', $a$matches moles of the compound rather than moles of oxygen atoms, omitting both O-per-formula-unit conversions$a$);

-- 16. [Molecules, Moles & Molar Mass · Skill 2 · ans C] id c81908c7-0ef8-48a0-b043-d1418e02183a
UPDATE questions SET
  question_text = $qt$A \(12.32\ \text{g}\) sample of pure magnesium sulfate heptahydrate, \(\text{MgSO}_4 \cdot 7\,\text{H}_2\text{O}\), is weighed out before it is dehydrated. Using atomic masses \(\text{Mg} = 24.31\), \(\text{S} = 32.07\), \(\text{O} = 16.00\), and \(\text{H} = 1.008\ \text{g/mol}\), the sample most nearly contains how many oxygen atoms?$qt$,
  options = $op$[{"label":"A","text":"\\(1.20\\times10^{23}\\) oxygen atoms"},{"label":"B","text":"\\(2.11\\times10^{23}\\) oxygen atoms"},{"label":"C","text":"\\(3.31\\times10^{23}\\) oxygen atoms"},{"label":"D","text":"\\(6.78\\times10^{23}\\) oxygen atoms"}]$op$::jsonb,
  explanation = $ex$This is a General Chemistry question that falls under the content category 'Stoichiometry (GC)'. The answer to this question is C because the conversion must (1) use the full hydrate molar mass to find moles, then (2) count oxygen atoms from BOTH the sulfate group and the bound water, then (3) scale by Avogadro's number. The molar mass of \(\text{MgSO}_4 \cdot 7\,\text{H}_2\text{O}\) is \(24.31 + 32.07 + 4(16.00) + 7\,[2(1.008) + 16.00] = 24.31 + 32.07 + 64.00 + 7(18.016) = 246.46 \approx 246.49\ \text{g/mol}\). Moles of hydrate: \(\frac{12.32\ \text{g}}{246.49\ \text{g/mol}} = 0.0500\ \text{mol}\). The controlling constraint is the oxygen inventory per formula unit: \(4\) oxygen atoms in \(\text{SO}_4\) plus \(7\) oxygen atoms (one per water) \(= 11\ \text{O}\) per formula unit. Moles of oxygen atoms: \(0.0500 \times 11 = 0.550\ \text{mol O}\). Multiplying by Avogadro's number: \(0.550 \times 6.022\times10^{23} = 3.31\times10^{23}\) oxygen atoms. (Choice A) This counts only the \(4\) oxygen atoms of the sulfate group and omits the \(7\) water oxygens, giving \(0.0500 \times 4 \times 6.022\times10^{23} = 1.20\times10^{23}\); the waters of hydration are part of the formula unit and their oxygen must be included. (Choice B) This counts only the \(7\) water oxygens and omits the \(4\) sulfate oxygens, giving \(0.0500 \times 7 \times 6.022\times10^{23} = 2.11\times10^{23}\); both oxygen sources belong to the same formula unit. (Choice D) This correctly uses \(11\) oxygen atoms per formula unit but divides the mass by the anhydrous molar mass \(\text{MgSO}_4 = 120.38\ \text{g/mol}\), yielding \(0.102\ \text{mol}\) and \(0.102 \times 11 \times 6.022\times10^{23} = 6.78\times10^{23}\); because the sample is the hydrate, the seven waters add mass and the full \(246.49\ \text{g/mol}\) must be used in the mass-to-mole step. This is a Scientific Reasoning and Problem Solving question because you must chain a hydrate molar-mass calculation, a per-formula-unit atom inventory that spans both the anion and the waters of crystallization, and a particle-count conversion, identifying which oxygen sources the controlling formula includes.$ex$,
  cognitive_skill = 2,
  difficulty = 'hard',
  estimated_time_seconds = 160
WHERE id = 'c81908c7-0ef8-48a0-b043-d1418e02183a';
DELETE FROM question_distractor_metadata WHERE question_id = 'c81908c7-0ef8-48a0-b043-d1418e02183a';
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype) VALUES
  ('c81908c7-0ef8-48a0-b043-d1418e02183a', 'A', 'process_step_confusion', $a$Counts only the sulfate oxygens (4 per formula unit) and drops the water oxygens, applying an incomplete atom-per-formula-unit ratio after a correct mass-to-mole step.$a$),
  ('c81908c7-0ef8-48a0-b043-d1418e02183a', 'B', 'process_step_confusion', $a$Counts only the water oxygens (7 per formula unit) and drops the sulfate oxygens, the mirror-image incomplete-inventory error.$a$),
